import React from 'react';
import { Toaster } from 'react-hot-toast';
import { SLAUPage } from './components/Lab1/SLAUPage';

function App() {
  return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100">
        <Toaster
            position="top-right"
            toastOptions={{
              duration: 4000,
              style: {
                background: '#363636',
                color: '#fff',
              },
              success: {
                style: {
                  background: '#10b981',
                },
              },
              error: {
                style: {
                  background: '#ef4444',
                },
              },
            }}
        />
        <SLAUPage />
      </div>
  );
}

export default App;
